import * as punycode from 'node:punycode';
import * as qs from 'node:querystring';
import { StringDecoder } from 'node:string_decoder';
import * as timers from 'node:timers';
function main(): void {
  function t(f: () => any): string { try { return String(f()); } catch (e: any) { return 'THROW ' + e.name + ': ' + e.message; } }
  const pd: any = punycode.decode, pe: any = punycode.encode, pa: any = punycode.toASCII, pu: any = punycode.toUnicode;
  console.log(t(() => pd()), '|', t(() => pe()), '|', t(() => pa()), '|', t(() => pu()));
  console.log(punycode.encode('mañana'), punycode.toASCII('mañana.com'));
  const q: any = qs;
  console.log(q.unescapeBuffer('a%20b+c', true).toString(), q.unescapeBuffer.length, q.unescape.length);
  console.log(Object.keys(new StringDecoder('utf8')).join(','));
  const tm: any = timers;
  const item: any = { _onTimeout() { console.log('tick'); } };
  tm.enroll(item, 5);
  console.log(item._idleTimeout);
  tm.active(item);
  console.log(typeof tm.promises.setTimeout, tm._unrefActive.length, tm.active.length, tm.enroll.length, tm.unenroll.length);
}
